import {
  ChangeDetectionStrategy,
  Component,
  OnInit,
  signal,
  ViewEncapsulation,
} from '@angular/core';
import { BaseClassTemplate } from '@_core/__base';

@Component({
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'aam-feature-print',
  templateUrl: './ztemplate-feature-print.html',
  styleUrls: ['./ztemplate-feature-print.scss'],
})
export class ZTemplateFeaturePrint extends BaseClassTemplate  {
  title = signal(0);
  constructor() {
    super();
    this._template.DATA.subscribe({
      next: (data) => {
        console.log({ DATA: (this.DATA = data) });
        setTimeout(() => {
          this.title.update(i => data.title);
          this._template._cdr.detectChanges();
        }, 100);
      },
    });
  }
  ngOnInit(): void {

  }
}
