import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { ZTemplateFeaturePrint } from './z-template-feature-print/ztemplate-feature-print';
import { FormAdmissionComponent } from './form-admission/form-admission';
import { FormExplanationComponent } from './form-explanation/form-explanation';
import { FormLeaveComponent } from './form-leave/form-leave';
import { ReportAttendance } from './report-attendance/report-attendance';
import { MenuIndexComponent } from '@_core/_route';
import { MenuSimpleIndex } from '@_core/_route/menu-simple-index/menu-simple-index';

export const routes: Routes = [
  {
    path: '',
    component: ZTemplateFeaturePrint,
    children: [
      {
        path: '',
        redirectTo: 'index',
        pathMatch: 'full',
      },
      {
        path: 'index',
        component: MenuSimpleIndex,
        data: {
          title: 'Feature Module',
        },
      },
      {
        path: 'form-admission',
        component: FormAdmissionComponent,
        data: {
          title: 'Form Admission',
        },
      },
      {
        path: 'form-explanation',
        component: FormExplanationComponent,
        data: {
          title: 'Form Explanation',
        },
      },
      {
        path: 'form-leave',
        component: FormLeaveComponent,
        data: {
          title: 'Form Leave',
        },
      },
      {
        path: 'report-attendance',
        component: ReportAttendance,
        data: {
          title: 'Report Attendace',
        },
      },
    ],
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class FeatureRoutingModule {
}
